{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_deployment_name AS dep, min(value) AS mn, max(value) AS mx, count(*) AS n FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='rate' GROUP BY ALL",
          "claim": "rate deployment availability is 0 across the whole abnormal window, versus 1 in normal operation, so its pod stayed gone."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, count(*) AS rate_spans FROM normal_traces WHERE service_name='rate' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name='rate'",
          "claim": "rate emits 1058 spans in the normal period and zero spans in the abnormal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) AS err_share, count(*) AS n FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "search's client calls to rate.Rate/GetRates appear in the abnormal window and fail, since rate has no live pod."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' GROUP BY ALL",
          "claim": "search logs 327 errors reading 'Failed to get rates from rate service'."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) AS err_share, count(*) AS n FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Server'",
          "claim": "search server spans fail about 99% of the time in the abnormal window, against 0% in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) AS err_share, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "frontend's calls to search.Search/Nearby all fail, and frontend HTTP server spans show about 48% errors."
        }
      ]
    }
  ]
}
